const express = require('express');
const crypto = require('crypto');
const { URL } = require('url');

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: false }));

const SESSION_SECRET = process.env.SESSION_SECRET || crypto.randomBytes(32).toString('hex');
const ALLOWED_REDIRECT_DOMAINS = ['app.example.com', 'dashboard.example.com', 'api.example.com'];

// Session store
const sessions = new Map();

function createSession(userId, role) {
  const sid = crypto.randomBytes(24).toString('base64url');
  const session = { userId, role, created: Date.now(), lastAccess: Date.now() };
  sessions.set(sid, session);
  return sid;
}

function validateSession(sid) {
  if (!sid || typeof sid !== 'string') return null;
  const session = sessions.get(sid);
  if (!session) return null;
  // 24-hour expiry
  if (Date.now() - session.created > 86400000) {
    sessions.delete(sid);
    return null;
  }
  session.lastAccess = Date.now();
  return session;
}

// HMAC-based CSRF token generation
function generateCsrfToken(sessionId) {
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const payload = `${sessionId}.${timestamp}`;
  const sig = crypto.createHmac('sha256', SESSION_SECRET).update(payload).digest('hex');
  return `${timestamp}.${sig}`;
}

function verifyCsrfToken(sessionId, token) {
  if (!token || typeof token !== 'string') return false;
  const parts = token.split('.');
  if (parts.length !== 2) return false;
  const [timestamp, sig] = parts;
  if (!/^\d+$/.test(timestamp)) return false;
  const ts = parseInt(timestamp, 10);
  const now = Math.floor(Date.now() / 1000);
  // Token valid for 1 hour
  if (Math.abs(now - ts) > 3600) return false;
  const payload = `${sessionId}.${timestamp}`;
  const expectedSig = crypto.createHmac('sha256', SESSION_SECRET).update(payload).digest('hex');
  // Constant-time comparison
  if (expectedSig.length !== sig.length) return false;
  return crypto.timingSafeEqual(Buffer.from(expectedSig, 'utf8'), Buffer.from(sig, 'utf8'));
}

// Redirect URL validation
function isAllowedRedirect(redirectUrl) {
  if (!redirectUrl || typeof redirectUrl !== 'string') return false;
  // Block javascript: and data: schemes
  if (/^\s*(javascript|data|vbscript):/i.test(redirectUrl)) return false;
  // Must be absolute URL with http(s)
  if (!/^https?:\/\//i.test(redirectUrl)) return false;
  try {
    const parsed = new URL(redirectUrl);
    // Get hostname directly - URL constructor already normalizes
    const hostname = parsed.hostname.toLowerCase();
    // Strict exact-match only against allowed domains (no subdomain wildcarding)
    return ALLOWED_REDIRECT_DOMAINS.includes(hostname);
  } catch (e) {
    return false;
  }
}

// Authentication middleware
function requireAuth(req, res, next) {
  const sid = req.cookies?.sid || req.headers['x-session-id'];
  const session = validateSession(sid);
  if (!session) {
    return res.status(401).json({ error: 'Authentication required' });
  }
  req.session = session;
  req.sessionId = sid;
  next();
}

// Simple cookie parser middleware
app.use((req, res, next) => {
  req.cookies = {};
  const cookieHeader = req.headers.cookie;
  if (cookieHeader) {
    cookieHeader.split(';').forEach(cookie => {
      const [name, ...rest] = cookie.trim().split('=');
      req.cookies[name.trim()] = rest.join('=').trim();
    });
  }
  next();
});

// Login endpoint
app.post('/auth/login', (req, res) => {
  const { username, password } = req.body;
  // Simplified auth check (in production, use bcrypt + DB)
  if (!username || !password) {
    return res.status(400).json({ error: 'Missing credentials' });
  }
  // Demo: accept test/test
  if (username === 'admin' && password === 'admin123') {
    const sid = createSession(username, 'admin');
    const csrf = generateCsrfToken(sid);
    res.cookie('sid', sid, { httpOnly: true, secure: true, sameSite: 'Strict' });
    return res.json({ csrf_token: csrf, user: { username, role: 'admin' } });
  }
  return res.status(401).json({ error: 'Invalid credentials' });
});

// OAuth callback with redirect
app.get('/auth/callback', requireAuth, (req, res) => {
  const { redirect_to } = req.query;
  if (!redirect_to) {
    return res.redirect('/dashboard');
  }
  if (isAllowedRedirect(redirect_to)) {
    return res.redirect(redirect_to);
  }
  return res.status(400).json({ error: 'Invalid redirect URL' });
});

// Protected API endpoint
app.post('/api/settings', requireAuth, (req, res) => {
  const csrfToken = req.headers['x-csrf-token'];
  if (!verifyCsrfToken(req.sessionId, csrfToken)) {
    return res.status(403).json({ error: 'Invalid CSRF token' });
  }
  // Process settings update
  const { theme, language, notifications } = req.body;
  res.json({ success: true, settings: { theme, language, notifications } });
});

// User profile with redirect after update
app.post('/api/profile/update', requireAuth, (req, res) => {
  const csrfToken = req.headers['x-csrf-token'];
  if (!verifyCsrfToken(req.sessionId, csrfToken)) {
    return res.status(403).json({ error: 'Invalid CSRF token' });
  }
  const { displayName, returnUrl } = req.body;
  if (returnUrl && isAllowedRedirect(returnUrl)) {
    return res.json({ success: true, redirect: returnUrl });
  }
  return res.json({ success: true, redirect: '/profile' });
});

const PORT = parseInt(process.env.PORT) || 3000;
app.listen(PORT, '127.0.0.1', () => {
  console.log(`Server running on port ${PORT}`);
});
